%--------------------------------------------------------------------------
%calculate test white and object colours under test source
[xyz,xyzwt]=spd2xyz(spd,10,0,MCRIrfls);

%--------------------------------------------------------------------------
for j=1:N
    %calculate corresponding colours under D65, the IPT white point
    xyzc=xyz2xyzcCAT02_(xyz(:,:,j),xyzwt(j,:),XYZwref,DD(j));
    %--------------------------------------------------------------------------

    %calculate IPT coordinates
    ipt(:,:,j)=XYZ2IPT_(xyzc);
    pti=[ipt(:,2:3,j),ipt(:,1,j)];
    %--------------------------------------------------------------------------

    %calulate special colour quality indicators Si
    Si(:,j)=exp(-0.5.*(((a3.*((pti(:,1)-a1).^2)+2*a5.*(pti(:,1)-a1).*(pti(:,2)-a2)+a4.*((pti(:,2)-a2).^2)))));
    %--------------------------------------------------------------------------

    %calculate general colour quality indicator Sa
    Sa(j)=geomean(Si(:,j));
    %--------------------------------------------------------------------------

    % Rescale Si and Sa indicators to Rm indices using a sigmoid rescaling function
    rescaling_pars=[21.7016   4.2106   2.4154];%Sa=0.5-->0; F4-->50; D65-->90; 1-->100
    switch rescaletype
        case 0 %no rescaling
            Rmi(:,j)=Si(:,j);Rm(j)=Sa(j);
        case 1 
            Rm(j)=SaScaling_(Sa(j),rescaling_pars);
            Rmi(:,j)=SaScaling_(Si(:,j),rescaling_pars);
    end
    %--------------------------------------------------------------------------
end
